72:     this.sunLight.shadow.mapSize.set(shadowMapSize, shadowMapSize);
73:     this.sunLight.shadow.bias = -0.00035;
74:     this.sunLight.shadow.normalBias = 0.025;
75: 
76:     const extent = Math.max(8, options.shadowCameraExtent ?? 28);
77:     const shadowCamera = this.sunLight.shadow.camera;
78:     shadowCamera.left = -extent;
79:     shadowCamera.right = extent;
80:     shadowCamera.top = extent;
81:     shadowCamera.bottom = -extent;
82:     shadowCamera.near = 1;
83:     shadowCamera.far = 90;
84: 
85:     this.lightsRoot.add(this.hemisphereLight, this.sunLight, this.sunLight.target);
